const $ = selector => document.querySelector(selector);
const clear = node => node.replaceChildren();
const make = (tag, className, text) => { const node = document.createElement(tag); if (className) node.className = className; if (text !== undefined) node.textContent = text; return node; };
const button = (text, className, handler) => { const node = make('button', className, text); node.type = 'button'; if (handler) node.addEventListener('click', handler); return node; };
const append = (node, ...children) => { children.flat().filter(Boolean).forEach(child => node.append(child)); return node; };
const get = (key, fallback) => { try { const value = localStorage.getItem(key); return value === null ? fallback : JSON.parse(value); } catch { return fallback; } };
const set = (key, value) => { try { localStorage.setItem(key, JSON.stringify(value)); return true; } catch { toast('Nie udało się zapisać danych na tym urządzeniu.'); return false; } };
const bool = key => localStorage.getItem(key) === 'true';
const shuffle = array => [...array].sort(() => Math.random() - .5);
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));
const dayKey = () => ['sun','mon','tue','wed','thu','fri','sat'][new Date().getDay()];
const toArray = (key) => { const value = get(key, []); return Array.isArray(value) ? value : []; };
const completedLessons = () => toArray(S.lessons);
const completedTasks = () => toArray(S.tasks);

const DEFAULT_PROGRESS = {version:1, gameXp:0, gameHistory:{}, selectedAnimal:'owl', sessionCount:0};
const MIGRATIONS = {1: old => ({...DEFAULT_PROGRESS, ...(old && typeof old === 'object' ? old : {}), version:2, gameHistory: {...DEFAULT_PROGRESS.gameHistory, ...(old?.gameHistory || {})}})};
function migrate(key, fromVer, toVer) { let data = get(key, null); for (let version = fromVer; version < toVer; version += 1) data = MIGRATIONS[version] ? MIGRATIONS[version](data) : data; set(key, data); return data; }
function loadProgress() { const saved = get(S.progress, null); if (!saved || typeof saved !== 'object') { set(S.progress, DEFAULT_PROGRESS); return {...DEFAULT_PROGRESS}; } const version = Number(saved.version) || 1; return migrate(S.progress, version, 2); }
let progress = loadProgress();
let preferences = get(S.preferences, {season:'auto', animations:true});
if (!preferences || typeof preferences !== 'object') preferences = {season:'auto', animations:true};
function saveProgress() { set(S.progress, progress); }
function savePreferences() { set(S.preferences, preferences); }
function migrateLegacyState() {
  const oldIds = get('planLekcji.completedTasks.v3', []);
  if (!localStorage.getItem(S.tasks) && Array.isArray(oldIds)) set(S.tasks, oldIds.filter(id => TASKS.some(item => item.id === id)));
  if (!localStorage.getItem(S.profile) && localStorage.getItem('planLekcji.profile.v3')) set(S.profile, get('planLekcji.profile.v3','none'));
  if (!localStorage.getItem(S.quiz) && bool('planLekcji.quizCompleted.v3')) { set(S.quiz,true); set(S.quizXp,Math.min(50,Number(get('planLekcji.quizPoints.v3',0)))); }
  if (!localStorage.getItem(S.memory) && bool('planLekcji.memoryCompleted.v3')) { set(S.memory,true); set(S.memoryXp,Number(get('planLekcji.memoryPoints.v3',0))); }
  if (!localStorage.getItem(S.truth) && bool('planLekcji.truthCompleted.v3')) { set(S.truth,true); set(S.truthXp,Math.min(25,Number(get('planLekcji.truthPoints.v3',0)))); }
  if (!localStorage.getItem(S.legacyXp)) { const xp = Number(get('plan51_xp',0)) || 0; if (xp > 0) set(S.legacyXp,xp); }
}

function taskXp() { const done = completedTasks(); return TASKS.filter(item => done.includes(item.id)).reduce((sum,item) => sum + item.xp, 0); }
function legacyGameXp() { return Number(get(S.quizXp,0) || 0) + Number(get(S.memoryXp,0) || 0) + Number(get(S.truthXp,0) || 0); }
function totalXp() { return taskXp() + legacyGameXp() + Number(get(S.legacyXp,0) || 0) + Number(progress.gameXp || 0); }
function autoSeason() { const month = new Date().getMonth(); if (month === 11 || month < 2) return 'winter'; if (month < 5) return 'spring'; if (month < 8) return 'summer'; return 'autumn'; }
function currentSeasonKey() { return preferences.season === 'auto' ? autoSeason() : (SEASONS[preferences.season] ? preferences.season : 'autumn'); }
function currentSeason() { return SEASONS[currentSeasonKey()]; }
function unlockedAnimals() { const xp = totalXp(); return ANIMALS.filter(animal => xp >= animal.threshold); }
function selectedAnimal() { const unlocked = unlockedAnimals(); return unlocked.find(animal => animal.id === progress.selectedAnimal) || unlocked[0] || ANIMALS[0]; }
function rewardToday() { return new Date().toISOString().slice(0,10); }
function playTone(kind = 'tap') { if (!bool(S.sound)) return; try { const Ctx = window.AudioContext || window.webkitAudioContext; if (!Ctx) return; const context = new Ctx(); const oscillator = context.createOscillator(); const gain = context.createGain(); oscillator.type = kind === 'wrong' ? 'triangle' : 'sine'; oscillator.frequency.value = kind === 'success' ? 660 : kind === 'wrong' ? 190 : 440; gain.gain.setValueAtTime(.0001, context.currentTime); gain.gain.exponentialRampToValueAtTime(.06, context.currentTime + .01); gain.gain.exponentialRampToValueAtTime(.0001, context.currentTime + .14); oscillator.connect(gain); gain.connect(context.destination); oscillator.start(); oscillator.stop(context.currentTime + .16); } catch {} }
function toast(message) { const node = $('#toast'); node.textContent = message; node.classList.add('visible'); clearTimeout(window.toastTimer); window.toastTimer = setTimeout(() => node.classList.remove('visible'), 2800); }

let selectedDay = dayKey(); if (!DAYS.some(day => day.key === selectedDay)) selectedDay = 'mon';
let activeView = 'plan', activeFilter = 'all', selectedSubject = 'Wszystkie', searchQuery = '', activeTask = null;
let gameState = {type:null, questions:[], index:0, score:0, answered:false, memoryCards:[], memoryOpen:[], memoryMatched:[], attempts:0, wordLetters:[], wordAnswer:'', wordUsed:[]};

function effectiveDays() { const custom = get(S.customPlan, null); if (!Array.isArray(custom) || custom.length !== DAYS.length) return DAYS; return DAYS.map((day,index) => { const candidate = custom[index]; return candidate && candidate.key === day.key && Array.isArray(candidate.lessons) ? candidate : day; }); }
function renderDays() { const root = $('#days'); clear(root); effectiveDays().forEach(day => { const node = button('', `day-tab${day.key === selectedDay ? ' active' : ''}${day.key === dayKey() ? ' today' : ''}`, () => { selectedDay = day.key; renderPlan(); }); node.dataset.day = day.key; node.setAttribute('role','tab'); node.setAttribute('aria-selected', String(day.key === selectedDay)); append(node, make('b','',day.short), make('small','',day.name.slice(0,3))); root.append(node); }); }
function renderPlan() {
  const day = effectiveDays().find(item => item.key === selectedDay) || effectiveDays()[0]; const showReligion = get(S.religion,false); const done = completedLessons();
  const lessons = day.lessons.map((row,index) => ({start:row[0],end:row[1],subject:row[2],teacher:row[3],room:row[4],icon:row[5],optional:row[6] === 'optional',id:`${day.key}-${index}`})).filter(item => showReligion || !item.optional);
  $('#selectedDayTitle').textContent = day.name; $('#dateLabel').textContent = selectedDay === dayKey() ? 'Dzisiaj · sprawdź swój spokojny rytm dnia' : 'Plan na wybrany dzień'; $('#lessonCount').textContent = `${lessons.length} ${lessons.length === 1 ? 'lekcja' : 'lekcji'}`; $('#optionalNote').textContent = showReligion ? 'Pokazujesz także religię. Możesz ją ukryć w zakładce „Więcej”.' : 'Religia jest ukryta. Możesz ją włączyć w zakładce „Więcej”.';
  const list = $('#lessonList'); clear(list);
  if (!lessons.length) { const empty = make('div','empty-state'); append(empty, make('span','', '🌤️'), make('strong','', 'Brak lekcji tego dnia'), make('p','', 'To dobry moment na odpoczynek albo krótką misję.')); list.append(empty); }
  lessons.forEach(lesson => { const finished = done.includes(lesson.id); const card = make('article',`lesson-card${finished ? ' done' : ''}`); const time = make('div','lesson-time'); append(time,make('b','',lesson.start),make('span','',lesson.end)); const body = make('div','lesson-body'); append(body, make('h3','',lesson.subject), make('p','',`${lesson.teacher} · sala ${lesson.room}`)); if (lesson.optional) body.append(make('span','optional-tag','opcjonalne')); const check = button(finished ? '✓' : '○',`lesson-check${finished ? ' checked' : ''}`,() => toggleLesson(lesson.id)); check.setAttribute('aria-label', `${finished ? 'Cofnij' : 'Oznacz'} ukończenie: ${lesson.subject}`); append(card,time,make('div','lesson-icon',lesson.icon),body,check); list.append(card); });
  const completed = lessons.filter(lesson => done.includes(lesson.id)).length; const percent = lessons.length ? completed / lessons.length * 100 : 0; $('#dayProgress').textContent = `${completed} / ${lessons.length}`; $('#dayProgressBar').style.width = `${percent}%`; const next = lessons.find(lesson => !done.includes(lesson.id)); $('#nextLesson').textContent = next ? next.subject : 'Plan zrealizowany!'; $('#nextLessonTime').textContent = next ? `${next.start} · sala ${next.room}` : 'Świetna robota — odpocznij'; renderDays(); renderHeader();
}
function toggleLesson(id) { const before = completedLessons(); const next = before.includes(id) ? before.filter(item => item !== id) : [...before,id]; set(S.lessons,next); playTone(next.length > before.length ? 'success' : 'tap'); toast(before.includes(id) ? 'Lekcja wróciła do planu.' : 'Lekcja oznaczona jako wykonaną!'); renderPlan(); renderProgress(); }
function renderHeader() { const xp = totalXp(); const profile = get(S.profile,'none'); $('#headerXp').textContent = `⭐ ${xp} XP`; $('#greeting').textContent = profile === 'girl' ? 'Twój szlak, odkrywczyni' : profile === 'boy' ? 'Twój szlak, odkrywco' : 'Twój szlak na dziś'; document.querySelectorAll('.profile-option').forEach(node => node.classList.toggle('selected',node.dataset.profile === profile)); $('#soundToggle').textContent = bool(S.sound) ? '🔊' : '🔇'; $('#soundToggle').setAttribute('aria-label',bool(S.sound) ? 'Wyłącz dźwięki' : 'Włącz dźwięki'); }
function renderSeason() { const season = currentSeason(); const companion = selectedAnimal(); const xp = totalXp(); const next = ANIMALS.find(animal => animal.threshold > xp); document.body.dataset.season = currentSeasonKey(); document.body.dataset.animations = preferences.animations ? 'on' : 'off'; $('#seasonChip').textContent = `${season.emoji} ${season.label} · ${preferences.season === 'auto' ? 'auto' : 'własny'}`; $('#seasonEmoji').textContent = season.emoji; $('#companionEmoji').textContent = companion.emoji; $('#seasonTitle').textContent = season.name; $('#seasonMessage').textContent = season.message; $('#seasonKicker').textContent = preferences.season === 'auto' ? 'TRYB AUTOMATYCZNY' : 'TWÓJ WYBRANY MOTYW'; $('#seasonProgressBar').style.width = `${next ? clamp((xp - companion.threshold) / (next.threshold - companion.threshold) * 100,0,100) : 100}%`; $('#seasonProgressText').textContent = next ? `${xp} XP · kolejny towarzysz za ${next.threshold - xp} XP` : `${xp} XP · cała kolekcja odblokowana!`; $('#worldTitle').textContent = season.name; $('#worldMessage').textContent = `${season.message} Aktualnie towarzyszy Ci ${companion.name}.`; $('#worldProgressBar').style.width = `${next ? clamp((xp - companion.threshold) / (next.threshold - companion.threshold) * 100,0,100) : 100}%`; $('#worldProgressText').textContent = next ? `${xp} XP · ${next.name} czeka za ${next.threshold - xp} XP` : `${xp} XP · wszystkie zwierzęta są z Tobą`; const art = $('#worldArt'); clear(art); unlockedAnimals().forEach(animal => art.append(make('span','',animal.emoji))); }

function taskVisible(item, done) { const matchesStatus = activeFilter === 'all' || (activeFilter === 'completed' && done) || (activeFilter === 'open' && !done); const matchesSubject = selectedSubject === 'Wszystkie' || item.subject === selectedSubject; const needle = searchQuery.trim().toLocaleLowerCase('pl'); const matchesText = !needle || [item.title,item.subject,item.desc,...item.exercises.map(ex => ex.question)].join(' ').toLocaleLowerCase('pl').includes(needle); return matchesStatus && matchesSubject && matchesText; }
function renderSubjects() { const root = $('#subjectChips'); clear(root); ['Wszystkie',...new Set(TASKS.map(item => item.subject))].forEach(subject => { const node = button(subject,`subject-chip${subject === selectedSubject ? ' active' : ''}`,() => { selectedSubject = subject; renderTasks(); }); root.append(node); }); }
function renderTasks() { const ids = completedTasks(); const visible = TASKS.filter(item => taskVisible(item,ids.includes(item.id))); $('#taskTotal').textContent = String(TASKS.length); $('#libraryResult').textContent = `Pokazujemy ${visible.length} z ${TASKS.length} zestawów · każdy zawiera 3 ćwiczenia.`; const root = $('#tasksGrid'); clear(root); if (!visible.length) { const empty = make('div','empty-state'); append(empty,make('span','', '🔎'),make('strong','', 'Nie znaleziono zestawów'),make('p','', 'Zmień słowo wyszukiwania lub wybierz inny przedmiot.')); root.append(empty); return; }
  visible.forEach(item => { const done = ids.includes(item.id); const locked = !done && totalXp() < item.unlock; const card = make('article',`task-card${done ? ' completed' : ''}${locked ? ' locked' : ''}`); card.style.setProperty('--task-color',item.subject === 'Matematyka' ? '#357cc9' : item.subject === 'Angielski' ? '#a35bbb' : item.subject === 'Przyroda' ? '#3d9b64' : '#d87935'); const heading = make('div','task-heading'); const titleBlock = make('div'); append(titleBlock,make('h3','',item.title),make('span','task-subject',item.subject)); const difficulty = make('span',`difficulty${item.diff === 'Średni' ? ' medium' : item.diff === 'Trudny' ? ' hard' : ''}`,item.diff); append(heading,titleBlock,difficulty); const meta = make('div','task-meta'); meta.append(make('span','',`⏱ ${item.time}`),make('span','xp',`+${item.xp} XP`)); const action = button(done ? '✓ Gotowe' : locked ? `🔒 ${item.unlock} XP` : 'Otwórz zestaw',`complete-button${done ? ' done-button' : ''}`,() => { if (locked) { toast(`Ten zestaw odblokuje się po zdobyciu ${item.unlock} XP.`); playTone('wrong'); } else openTask(item); }); if (done) action.disabled = true; meta.append(action); const content = make('div','task-content'); append(content,heading,make('p','',item.desc),meta); append(card,make('div','task-number',String(TASKS.indexOf(item)+1).padStart(2,'0')),content); root.append(card); }); }
function openTask(item) { activeTask = item; $('#taskModalKicker').textContent = `${item.subject.toUpperCase()} · ${item.diff.toUpperCase()}`; $('#taskModalTitle').textContent = item.title; $('#taskModalIntro').textContent = `${item.desc} Wykonaj po kolei trzy ćwiczenia. Odpowiedzi wpisujesz tylko dla siebie — aplikacja ich nie wysyła i nie zapisuje.`; const stage = $('#taskStage'); clear(stage); stage.classList.remove('show-hints'); item.exercises.forEach((itemExercise,index) => { const line = make('section','task-item'); append(line,make('b','',`${index + 1}. ${itemExercise.question}`)); const input = document.createElement('input'); input.className = 'task-answer'; input.autocomplete = 'off'; input.placeholder = 'Twoja odpowiedź lub notatka…'; input.setAttribute('aria-label',`Odpowiedź do zadania ${index + 1}`); line.append(input); const hint = make('p','task-hint',`Podpowiedź: ${itemExercise.hint}${itemExercise.answer ? ` Oczekiwany wynik: ${itemExercise.answer}.` : ''}`); line.append(hint); stage.append(line); }); $('#taskHintButton').textContent = 'Pokaż podpowiedzi'; $('#taskModal').classList.remove('hidden'); }
function finishTask() { if (!activeTask) return; const ids = completedTasks(); if (!ids.includes(activeTask.id)) { set(S.tasks,[...ids,activeTask.id]); playTone('success'); toast(`+${activeTask.xp} XP · zestaw wykonany!`); } $('#taskModal').classList.add('hidden'); activeTask = null; renderAll(); }

function gameHistory(type) { return progress.gameHistory[type] || {sessions:0,best:0,lastReward:''}; }
function renderGames() { const root = $('#gamesGrid'); clear(root); GAMES.forEach(game => { const history = gameHistory(game.id); const card = make('article','game-card'); card.dataset.symbol = game.symbol; card.style.setProperty('--game-color',game.color); append(card,make('div','game-icon',game.icon),make('span','game-label',game.label),make('h2','',game.title),make('p','',game.desc)); const status = make('span','game-status', history.sessions ? `Rekord: ${history.best}/${game.id === 'memory' ? '8' : game.id === 'sprint' ? '8' : game.id === 'word' ? '5' : '10'} · ${history.lastReward === rewardToday() ? 'bonus dzisiaj odebrany' : 'bonus dzisiaj dostępny'}` : 'Pierwsza sesja czeka na Ciebie'); const start = button('Graj', 'play-button', () => openGame(game.id)); append(card,status,start); root.append(card); }); renderAnimals(); }
function renderAnimals() { const animals = unlockedAnimals(); const root = $('#animalCollection'); clear(root); $('#collectionCount').textContent = `${animals.length} / ${ANIMALS.length}`; ANIMALS.forEach(animal => { const unlocked = animals.some(item => item.id === animal.id); const card = button('',`animal-card${unlocked ? ' unlocked' : ''}${progress.selectedAnimal === animal.id && unlocked ? ' selected' : ''}`,() => { if (!unlocked) { toast(`Ten towarzysz pojawi się po ${animal.threshold} XP.`); return; } progress.selectedAnimal = animal.id; saveProgress(); renderSeason(); renderAnimals(); playTone('tap'); }); card.disabled = !unlocked; append(card,make('span','animal-emoji',unlocked ? animal.emoji : '🔒'),make('b','',unlocked ? animal.name : '???'),make('small','',unlocked ? (progress.selectedAnimal === animal.id ? 'Towarzyszy Ci' : 'Wybierz') : `${animal.threshold} XP`)); root.append(card); }); }
function randomQuestion(source, count) { return shuffle(source).slice(0,count); }
function openGame(type) { gameState = {type, questions:[], index:0, score:0, answered:false, memoryCards:[], memoryOpen:[], memoryMatched:[], attempts:0, wordLetters:[], wordAnswer:'', wordUsed:[]}; $('#gameModal').classList.remove('hidden'); playTone('tap'); if (type === 'memory') { setupMemory(); return; } if (type === 'word') { gameState.questions = randomQuestion(WORDS,5); setupWord(); return; } gameState.questions = randomQuestion(type === 'quiz' ? QUIZ : type === 'truth' ? TRUTH : SPRINT, type === 'sprint' ? 8 : 10); renderQuestion(); }
function closeGame() { $('#gameModal').classList.add('hidden'); }
function updateGameProgress(total) { $('#gameScore').textContent = `${gameState.score} pkt`; $('#gameProgress').firstElementChild.style.width = `${total ? gameState.index / total * 100 : 0}%`; }
function renderQuestion() { const current = gameState.questions[gameState.index]; const isTruth = gameState.type === 'truth'; $('#modalKicker').textContent = gameState.type === 'quiz' ? 'MISJA: QUIZ' : gameState.type === 'truth' ? 'MISJA: FAKT CZY FIKCJA' : 'MATEMATYCZNY SPRINT'; $('#modalTitle').textContent = current.q; $('#gameInstruction').textContent = `Pytanie ${gameState.index + 1} z ${gameState.questions.length}. Pomyśl chwilę — po odpowiedzi zobaczysz wyjaśnienie.`; updateGameProgress(gameState.questions.length); const stage = $('#gameStage'); clear(stage); const answers = isTruth ? [{label:'Prawda',value:'true'},{label:'Fałsz',value:'false'}] : shuffle(current.a).map(value => ({label:value,value})); const answerBox = make('div','answers'); answers.forEach(answer => answerBox.append(button(answer.label,'answer-button',() => answerQuestion(answer.value)))); stage.append(answerBox); $('#gameMessage').replaceChildren(); }
function answerQuestion(value) { if (gameState.answered) return; gameState.answered = true; const current = gameState.questions[gameState.index]; const correctValue = gameState.type === 'truth' ? String(current.c) : current.c; const correct = value === correctValue; document.querySelectorAll('.answer-button').forEach(node => { node.disabled = true; if (node.textContent === correctValue || node.dataset.answer === correctValue) node.classList.add('correct'); if (!correct && node.textContent === value) node.classList.add('wrong'); }); if (correct) { gameState.score += 1; playTone('success'); } else playTone('wrong'); $('#gameScore').textContent = `${gameState.score} pkt`; const message = $('#gameMessage'); clear(message); const feedback = make('span',correct ? 'feedback-good' : 'feedback-help',correct ? 'Dobrze! ' : 'Zapamiętaj: '); const next = button(gameState.index + 1 === gameState.questions.length ? 'Zobacz wynik →' : 'Następne →','next-button',() => { gameState.index += 1; gameState.answered = false; gameState.index < gameState.questions.length ? renderQuestion() : finishGame(); }); append(message,feedback,document.createTextNode(current.e),next); }
function setupMemory() { const cards = shuffle(PAIRS.flatMap(pair => [{pair:pair[0],text:pair[0],icon:pair[2],kind:'a'},{pair:pair[0],text:pair[1],icon:pair[2],kind:'b'}])); gameState.memoryCards = cards; $('#modalKicker').textContent = 'MISJA: LABORATORIUM PAR'; $('#modalTitle').textContent = 'Połącz pojęcie z jego znaczeniem'; $('#gameInstruction').textContent = 'Odkrywaj po dwie karty. Bez limitu czasu — sprawdź, czy pobijesz własny rekord prób.'; $('#gameScore').textContent = '0 / 8 par'; $('#gameProgress').firstElementChild.style.width = '0%'; const stage = $('#gameStage'); clear(stage); const board = make('div','memory-board'); cards.forEach((card,index) => { const node = button('','memory-card',() => flipMemory(index)); node.dataset.index = String(index); const inner = make('span','memory-inner'); const front = make('span','memory-front','?'); const back = make('span','memory-back'); append(back,make('b','',card.icon),make('small','',card.text)); append(inner,front,back); node.append(inner); board.append(node); }); stage.append(board); $('#gameMessage').textContent = 'Znajdź wszystkie 8 par.'; }
function flipMemory(index) { if (gameState.memoryOpen.length >= 2 || gameState.memoryMatched.includes(index) || gameState.memoryOpen.includes(index)) return; gameState.memoryOpen.push(index); const node = document.querySelector(`.memory-card[data-index="${index}"]`); node?.classList.add('flipped'); playTone('tap'); if (gameState.memoryOpen.length < 2) return; gameState.attempts += 1; const [first,second] = gameState.memoryOpen; const one = gameState.memoryCards[first], two = gameState.memoryCards[second]; const match = one.pair === two.pair && one.kind !== two.kind; if (match) { gameState.memoryMatched.push(first,second); gameState.memoryOpen = []; document.querySelector(`.memory-card[data-index="${first}"]`)?.classList.add('matched'); document.querySelector(`.memory-card[data-index="${second}"]`)?.classList.add('matched'); gameState.score = gameState.memoryMatched.length / 2; $('#gameScore').textContent = `${gameState.score} / 8 par`; $('#gameProgress').firstElementChild.style.width = `${gameState.memoryMatched.length / gameState.memoryCards.length * 100}%`; playTone('success'); if (gameState.memoryMatched.length === gameState.memoryCards.length) setTimeout(finishGame,350); } else { playTone('wrong'); setTimeout(() => { gameState.memoryOpen.forEach(item => document.querySelector(`.memory-card[data-index="${item}"]`)?.classList.remove('flipped')); gameState.memoryOpen = []; },650); } }
function setupWord() { const current = gameState.questions[gameState.index]; gameState.wordLetters = shuffle([...current.word]); gameState.wordAnswer = ''; gameState.wordUsed = []; $('#modalKicker').textContent = 'MISJA: SŁOWNY TROP'; $('#modalTitle').textContent = `Hasło ${gameState.index + 1} z ${gameState.questions.length}`; $('#gameInstruction').textContent = current.hint; $('#gameScore').textContent = `${gameState.score} pkt`; $('#gameProgress').firstElementChild.style.width = `${gameState.index / gameState.questions.length * 100}%`; renderWordBoard(); }
function renderWordBoard() { const stage = $('#gameStage'); clear(stage); const board = make('div','word-board'); const built = make('div','built-word',gameState.wordAnswer || '—'); built.setAttribute('aria-label','Ułożone hasło'); const bank = make('div','letter-bank'); gameState.wordLetters.forEach((letter,index) => { const used = gameState.wordUsed.includes(index); const node = button(letter,'letter-button',() => { if (used) return; gameState.wordUsed.push(index); gameState.wordAnswer += letter; renderWordBoard(); }); node.disabled = used; if (used) node.classList.add('used'); bank.append(node); }); const actions = make('div','word-actions'); const erase = button('Cofnij','secondary-action',() => { const index = gameState.wordUsed.pop(); if (index !== undefined) gameState.wordAnswer = gameState.wordAnswer.slice(0,-1); renderWordBoard(); }); const check = button('Sprawdź','next-button',checkWord); append(actions,erase,check); append(board,built,bank,actions); stage.append(board); $('#gameMessage').textContent = 'Ułóż wyraz, a potem sprawdź odpowiedź.'; }
function checkWord() { const current = gameState.questions[gameState.index]; if (gameState.wordAnswer !== current.word) { $('#gameMessage').textContent = 'To jeszcze nie to. Skorzystaj z podpowiedzi i spróbuj ponownie.'; playTone('wrong'); return; } gameState.score += 1; playTone('success'); const message = $('#gameMessage'); clear(message); append(message,make('span','feedback-good','Dobrze! '),document.createTextNode(`Hasło „${current.word}” jest poprawne.`),button(gameState.index + 1 === gameState.questions.length ? 'Zobacz wynik →' : 'Następne →','next-button',() => { gameState.index += 1; gameState.index < gameState.questions.length ? setupWord() : finishGame(); })); document.querySelectorAll('.letter-button,.word-actions button').forEach(node => node.disabled = true); }
function finishGame() { const type = gameState.type; const max = type === 'memory' ? 8 : gameState.questions.length; const score = gameState.score; $('#gameProgress').firstElementChild.style.width = '100%'; $('#modalKicker').textContent = 'SESJA UKOŃCZONA'; $('#modalTitle').textContent = `Wynik: ${score}/${max}`; const stage = $('#gameStage'); clear(stage); const result = make('div','result-card'); append(result,make('div','result-stars',score >= Math.ceil(max*.8) ? '🌟🌟🌟' : score >= Math.ceil(max*.5) ? '🌟🌟' : '🌟'),make('strong','',score >= Math.ceil(max*.8) ? 'Świetny wynik!' : 'Dobra próba!'),make('span','', 'Każda sesja ćwiczy pamięć, wiedzę i wytrwałość.')); stage.append(result); const reward = awardGame(type,score,max); const msg = $('#gameMessage'); clear(msg); msg.textContent = reward ? `Zdobywasz +${reward} XP za dzisiejszą sesję!` : 'Bonus XP na dziś został już odebrany. Możesz ćwiczyć dalej dla rekordu!'; renderAll(); }
function awardGame(type, score, max) { const today = rewardToday(); const history = gameHistory(type); let reward = 0; const oldKeys = {quiz:[S.quiz,S.quizXp,50],memory:[S.memory,S.memoryXp,30],truth:[S.truth,S.truthXp,25]}; if (oldKeys[type] && !bool(oldKeys[type][0])) { const [completeKey,xpKey,cap] = oldKeys[type]; const legacyReward = Math.max(type === 'memory' ? 10 : 4,Math.round(score / max * cap)); set(completeKey,true); set(xpKey,legacyReward); reward = legacyReward; }
  if (!reward && history.lastReward !== today) { reward = Math.max(4,Math.round(score / Math.max(max,1) * (type === 'memory' ? 18 : 14))); progress.gameXp += reward; }
  progress.gameHistory = {...progress.gameHistory,[type]:{sessions:history.sessions + 1,best:Math.max(history.best,score),lastReward:reward ? today : history.lastReward}}; progress.sessionCount += 1; saveProgress(); playTone('success'); return reward; }

function badgeData() { const completed = completedTasks().length, lessons = completedLessons().length, games = progress.sessionCount, animals = unlockedAnimals().length, xp = totalXp(); return [{icon:'🌱',name:'Pierwszy krok',desc:'Ukończ 1 zestaw',ok:completed >= 1},{icon:'📚',name:'Czytelnik misji',desc:'Ukończ 10 zestawów',ok:completed >= 10},{icon:'🎯',name:'Plan na medal',desc:'Oznacz 10 lekcji',ok:lessons >= 10},{icon:'🧠',name:'Gracz wiedzy',desc:'Zagraj 3 sesje',ok:games >= 3},{icon:'🔥',name:'W rytmie nauki',desc:'Zbierz 150 XP',ok:xp >= 150},{icon:'🦊',name:'Przyjaciel szlaku',desc:'Odblokuj 3 zwierzęta',ok:animals >= 3},{icon:'⭐',name:'Mistrz małych kroków',desc:'Ukończ 25 zestawów',ok:completed >= 25},{icon:'🏔️',name:'Legenda szlaku',desc:'Zbierz 500 XP',ok:xp >= 500}]; }
function renderProgress() { const xp = totalXp(), level = Math.floor(xp / 50) + 1, rank = level >= 12 ? 'Legenda Szlaku' : level >= 8 ? 'Mistrz Odkryć' : level >= 4 ? 'Praktyk' : 'Odkrywca'; const until = level * 50 - xp; $('#progressRank').textContent = rank; $('#progressLevel').textContent = `Poziom ${level} · następny poziom za ${Math.max(0,until)} XP`; $('#progressXp').textContent = xp; $('#levelProgressBar').style.width = `${xp % 50 / 50 * 100}%`; $('#progressLessons').textContent = completedLessons().length; $('#progressTasks').textContent = completedTasks().length; $('#progressGames').textContent = progress.sessionCount; $('#progressAnimals').textContent = unlockedAnimals().length; const badges = badgeData(); $('#badgeCount').textContent = `${badges.filter(item => item.ok).length} / ${badges.length}`; const root = $('#badgesGrid'); clear(root); badges.forEach(badge => { const item = make('article',`badge${badge.ok ? ' unlocked' : ''}`); append(item,make('span','badge-icon',badge.ok ? badge.icon : '🔒')); const copy = make('div'); append(copy,make('b','',badge.name),make('small','',badge.ok ? 'Odblokowano!' : badge.desc)); item.append(copy); root.append(item); }); }
function renderMore() { const note = get(S.notebook,''); $('#notebookText').value = typeof note === 'string' ? note : ''; $('#notebookCount').textContent = `${$('#notebookText').value.length} / 3000`; $('#religionState').textContent = get(S.religion,false) ? 'Włączone' : 'Wyłączone'; $('#themeState').textContent = preferences.season === 'auto' ? 'Auto' : SEASONS[preferences.season].label; $('#motionState').textContent = preferences.animations ? 'Włączone' : 'Wyłączone'; }
function renderAll() { renderSeason(); renderPlan(); renderSubjects(); renderTasks(); renderGames(); renderProgress(); renderHeader(); renderMore(); }
function switchView(view) { activeView = view; document.querySelectorAll('.view').forEach(node => node.classList.toggle('active',node.id === `view-${view}`)); document.querySelectorAll('.tab').forEach(node => { const selected = node.dataset.view === view; node.classList.toggle('active',selected); node.setAttribute('aria-selected',String(selected)); }); if (view === 'tasks') { renderSubjects(); renderTasks(); } if (view === 'games') { renderGames(); renderSeason(); } if (view === 'progress') renderProgress(); if (view === 'more') renderMore(); window.scrollTo({top:0,behavior:preferences.animations ? 'smooth' : 'auto'}); }

function openSeasonPicker() { const root = $('#seasonOptions'); clear(root); Object.entries(SEASONS).forEach(([key,season]) => { const selected = preferences.season === key; const option = button('',`season-option${selected ? ' selected' : ''}`,() => { preferences.season = key; savePreferences(); $('#seasonModal').classList.add('hidden'); renderAll(); toast(key === 'auto' ? 'Motyw będzie dopasowany automatycznie.' : `Wybrano: ${season.name}.`); }); append(option,make('span','option-emoji',season.emoji),(() => { const copy = make('span'); append(copy,make('b','',season.name),make('small','',season.description)); return copy; })()); root.append(option); }); $('#seasonModal').classList.remove('hidden'); }
function openEditor() { const day = effectiveDays().find(item => item.key === selectedDay) || DAYS[0]; const fields = $('#editorFields'); clear(fields); day.lessons.forEach((lesson,index) => { const field = make('fieldset','editor-field'); field.append(make('legend','',`${lesson[0]}–${lesson[1]}`)); [['subject',lesson[2],'Przedmiot'],['teacher',lesson[3],'Nauczyciel'],['room',lesson[4],'Sala']].forEach(([key,value,label]) => { const input = document.createElement('input'); input.required = key === 'subject'; input.value = value; input.dataset.editorKey = key; input.dataset.index = String(index); input.setAttribute('aria-label',label); field.append(input); }); fields.append(field); }); $('#planEditorModal').classList.remove('hidden'); }
function saveEditor() { const original = effectiveDays().find(item => item.key === selectedDay) || DAYS[0]; const day = JSON.parse(JSON.stringify(original)); document.querySelectorAll('[data-editor-key]').forEach(input => { const index = Number(input.dataset.index); const position = input.dataset.editorKey === 'subject' ? 2 : input.dataset.editorKey === 'teacher' ? 3 : 4; day.lessons[index][position] = input.value.trim() || day.lessons[index][position]; }); set(S.customPlan,effectiveDays().map(item => item.key === day.key ? day : item)); $('#planEditorModal').classList.add('hidden'); toast('Plan zapisany na tym urządzeniu.'); renderPlan(); }
function restorePlan() { if (!confirm('Przywrócić przykładowy plan? Własne edycje planu zostaną usunięte, ale XP i gry pozostaną.')) return; localStorage.removeItem(S.customPlan); $('#planEditorModal').classList.add('hidden'); renderPlan(); toast('Przywrócono przykładowy plan.'); }
function resetAll() { if (!confirm('Czy na pewno wyzerować cały postęp, gry, odznaki i ustawienia? Plan można zachować osobno.')) return; [S.tasks,S.lessons,S.profile,S.quiz,S.quizXp,S.memory,S.memoryXp,S.truth,S.truthXp,S.notebook,S.customPlan,S.progress,S.preferences].forEach(key => localStorage.removeItem(key)); progress = {...DEFAULT_PROGRESS}; preferences = {season:'auto',animations:true}; toast('Postęp został wyzerowany.'); renderAll(); }
function prepareFeedback(event) { event.preventDefault(); const name = $('#feedbackName').value.trim(); const message = $('#feedbackMessage').value.trim(); if (!message) return; const body = [`Opinia z aplikacji Plan Lekcji${name ? `\nOd: ${name}` : ''}`, '', message, '', 'Wiadomość została przygotowana lokalnie w aplikacji Plan Lekcji.'].join('\n'); window.location.href = `mailto:ronoc2020@gmail.com?subject=${encodeURIComponent('Aplikacja Plan Lekcji')}&body=${encodeURIComponent(body)}`; toast('Otwieram program pocztowy z przygotowaną wiadomością.'); }

function bindEvents() {
  document.querySelectorAll('.tab').forEach(node => node.addEventListener('click',() => switchView(node.dataset.view)));
  document.querySelectorAll('.profile-option').forEach(node => node.addEventListener('click',() => { set(S.profile,node.dataset.profile); renderHeader(); toast('Powitanie zapisane.'); playTone('success'); }));
  document.querySelectorAll('.filter-button').forEach(node => node.addEventListener('click',() => { activeFilter = node.dataset.filter; document.querySelectorAll('.filter-button').forEach(buttonNode => buttonNode.classList.toggle('active',buttonNode === node)); renderTasks(); }));
  $('#taskSearch').addEventListener('input',event => { searchQuery = event.target.value; renderTasks(); });
  $('#religionToggle').addEventListener('click',() => { set(S.religion,!get(S.religion,false)); renderPlan(); renderMore(); });
  $('#themeSettingsButton').addEventListener('click',openSeasonPicker); $('#chooseSeasonButton').addEventListener('click',openSeasonPicker); $('#seasonChip').addEventListener('click',openSeasonPicker);
  $('#motionToggle').addEventListener('click',() => { preferences.animations = !preferences.animations; savePreferences(); renderSeason(); renderMore(); toast(preferences.animations ? 'Łagodne animacje są włączone.' : 'Animacje są zatrzymane.'); });
  $('#resetPlanButton').addEventListener('click',() => { if (confirm('Przywrócić przykładowy plan i wyczyścić zaznaczenia lekcji?')) { localStorage.removeItem(S.lessons); localStorage.removeItem(S.customPlan); renderPlan(); toast('Przywrócono przykładowy plan.'); } });
  $('#resetAllButton').addEventListener('click',resetAll); $('#resetButton').addEventListener('click',resetAll); $('#soundToggle').addEventListener('click',() => { set(S.sound,!bool(S.sound)); renderHeader(); playTone('success'); toast(bool(S.sound) ? 'Dźwięki włączone.' : 'Dźwięki wyłączone.'); });
  $('#closeGameButton').addEventListener('click',closeGame); $('#gameModal').addEventListener('click',event => { if (event.target.id === 'gameModal') closeGame(); });
  $('#closeTaskButton').addEventListener('click',() => $('#taskModal').classList.add('hidden')); $('#taskModal').addEventListener('click',event => { if (event.target.id === 'taskModal') $('#taskModal').classList.add('hidden'); }); $('#taskHintButton').addEventListener('click',() => { const stage = $('#taskStage'); stage.classList.toggle('show-hints'); $('#taskHintButton').textContent = stage.classList.contains('show-hints') ? 'Ukryj podpowiedzi' : 'Pokaż podpowiedzi'; }); $('#finishTaskButton').addEventListener('click',finishTask);
  $('#closeSeasonButton').addEventListener('click',() => $('#seasonModal').classList.add('hidden')); $('#seasonModal').addEventListener('click',event => { if (event.target.id === 'seasonModal') $('#seasonModal').classList.add('hidden'); });
  $('#editPlanButton').addEventListener('click',openEditor); $('#closeEditorButton').addEventListener('click',() => $('#planEditorModal').classList.add('hidden')); $('#restoreDayButton').addEventListener('click',restorePlan); $('#planEditorForm').addEventListener('submit',event => { event.preventDefault(); saveEditor(); });
  $('#notebookText').addEventListener('input',event => $('#notebookCount').textContent = `${event.target.value.length} / 3000`); $('#saveNotebook').addEventListener('click',() => { set(S.notebook,$('#notebookText').value); toast('Notatka zapisana na tym urządzeniu.'); playTone('success'); }); $('#feedbackForm').addEventListener('submit',prepareFeedback);
  document.addEventListener('keydown',event => { if (event.key === 'Escape') { closeGame(); $('#taskModal').classList.add('hidden'); $('#seasonModal').classList.add('hidden'); $('#planEditorModal').classList.add('hidden'); } });
}

migrateLegacyState(); if (localStorage.getItem(S.sound) === null) set(S.sound,true); bindEvents(); renderAll();
